struct SegTree {
    int n;
    vector<int> st;
    SegTree(int n=0): n(n), st(4*n+4, 0) {}
    void update(int p, int val, int node, int l, int r){
        if(l==r){ st[node]=max(st[node], val); return; }
        int m=(l+r)>>1;
        if(p<=m) update(p,val,node<<1,l,m);
        else update(p,val,node<<1|1,m+1,r);
        st[node]=max(st[node<<1], st[node<<1|1]);
    }
    void update(int p, int val){ update(p,val,1,1,n); }
    int query(int ql, int qr, int node, int l, int r){
        if(ql>r||qr<l) return 0;
        if(ql<=l&&r<=qr) return st[node];
        int m=(l+r)>>1;
        return max(query(ql,qr,node<<1,l,m), query(ql,qr,node<<1|1,m+1,r));
    }
    int query(int l, int r){
        if(l>r) return 0;
        return query(l,r,1,1,n);
    }
};

