#define MAX_STATIONS 100000
#define MAX_PASSENGERS 200000

typedef struct {
    int start;
    int end;
} Trip;

int cmp(const void *a, const void *b) {
    Trip *t1 = (Trip *)a;
    Trip *t2 = (Trip *)b;
    if (t1->start != t2->start)
        return t1->start - t2->start;
    return t1->end - t2->end;
}

int main() {
    int n;
    scanf("%d", &n);

    Trip trips[MAX_PASSENGERS];
    int diff[MAX_STATIONS + 2] = {0};

    for (int i = 0; i < n; i++) {
        scanf("%d %d", &trips[i].start, &trips[i].end);
        trips[i].end--; // Convert to inclusive range for difference array
        diff[trips[i].start]++;
        diff[trips[i].end + 1]--;
    }

    // Policy 2: find maximum overlap using difference array
    int policy2 = 0;
    int current = 0;
    for (int i = 1; i <= MAX_STATIONS; i++) {
        current += diff[i];
        if (current > policy2)
            policy2 = current;
    }

    // Policy 1: sort by start time, then use greedy with min-heap of end times
    qsort(trips, n, sizeof(Trip), cmp);

    // Min-heap for end times (simple array-based heap)
    int heap[MAX_PASSENGERS];
    int heap_size = 0;
    int policy1 = 0;

    for (int i = 0; i < n; i++) {
        // Remove trips that have ended before current trip starts
        while (heap_size > 0 && heap[0] < trips[i].start) {
            // Remove min element
            heap[0] = heap[--heap_size];
            // Sift down
            int idx = 0;
            while (1) {
                int smallest = idx;
                int left = 2 * idx + 1;
                int right = 2 * idx + 2;
                if (left < heap_size && heap[left] < heap[smallest])
                    smallest = left;
                if (right < heap_size && heap[right] < heap[smallest])
                    smallest = right;
                if (smallest != idx) {
                    int temp = heap[idx];
                    heap[idx] = heap[smallest];
                    heap[smallest] = temp;
                    idx = smallest;
                } else {
                    break;
                }
            }
        }
        // Add current trip's end to heap
        heap[heap_size++] = trips[i].end;
        // Sift up
        int idx = heap_size - 1;
        while (idx > 0) {
            int parent = (idx - 1) / 2;
            if (heap[idx] < heap[parent]) {
                int temp = heap[idx];
                heap[idx] = heap[parent];
                heap[parent] = temp;
                idx = parent;
            } else {
                break;
            }
        }
        if (heap_size > policy1)
            policy1 = heap_size;
    }

    printf("%d %d\n", policy1, policy2);

    return 0;
}

