        int policy2 = computePolicy2(intervals);

        System.out.println(policy1 + " " + policy2);
    }

    static int computePolicy1(int[][] intervals) {
        int n = intervals.length;
        // Maintain a multiset of end times of occupied seats
        // For each passenger, we need to find a seat whose end time <= start time
        // In the worst case, the passenger takes the seat with the latest end time
        // (to maximize future conflicts)

        PriorityQueue<Integer> pq = new PriorityQueue<>(); // min-heap of end times
        // Actually, we need a multiset that supports removing the element with the latest end time
        // that is <= start time. This can be done with a TreeMap.

        TreeMap<Integer, Integer> endTimes = new TreeMap<>(); // end time -> count
        int maxSeats = 0;
        int currentSeats = 0;

        for (int i = 0; i < n; i++) {
            int start = intervals[i][0];
            int end = intervals[i][1];

            // Find the seat with the latest end time that is <= start
            // This is the seat that the passenger will take in the worst case
            Integer key = endTimes.floorKey(start);
            if (key != null) {
                // Take this seat
                int count = endTimes.get(key);
                if (count == 1) {
                    endTimes.remove(key);
                } else {
                    endTimes.put(key, count - 1);
                }
                // Update the end time to the new passenger's end time
                endTimes.put(end, endTimes.getOrDefault(end, 0) + 1);
            } else {
                // Need a new seat
                endTimes.put(end, endTimes.getOrDefault(end, 0) + 1);
                currentSeats++;
                maxSeats = Math.max(maxSeats, currentSeats);
            }
        }

        return maxSeats;
    }

    static int computePolicy2(int[][] intervals) {
        int n = intervals.length;
        int[] starts = new int[n];
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = intervals[i][0];
            ends[i] = intervals[i][1];
        }
        Arrays.sort(starts);
        Arrays.sort(ends);

        int maxOverlap = 0;
        int currentOverlap = 0;
        int i = 0, j = 0;
        while (i < n && j < n) {
            if (starts[i] < ends[j]) {
                currentOverlap++;
                maxOverlap = Math.max(maxOverlap, currentOverlap);
                i++;
            } else {
                currentOverlap--;
                j++;
            }
        }

        return maxOverlap;
    }
}

