Output two integers policy1 and policy2, maybe one per line. We'll print both separated by space.
*/

public class Main {
    static class SegTree {
        int n;
        int[] max, lazy;
        SegTree(int size) {
            n = 1;
            while (n < size) n <<= 1;
            max = new int[n << 1];
            lazy = new int[n << 1];
        }
        void add(int l, int r, int v) { add(1, 0, n, l, r, v); }
        void add(int idx, int nl, int nr, int l, int r, int v) {
            if (r <= nl || nr <= l) return;
            if (l <= nl && nr <= r) {
                max[idx] += v;
                lazy[idx] += v;
                return;
            }
            int mid = (nl + nr) >>> 1;
            add(idx << 1, nl, mid, l, r, v);
            add(idx << 1 | 1, mid, nr, l, r, v);
            max[idx] = lazy[idx] + Math.max(max[idx << 1], max[idx << 1 | 1]);
        }
        int queryMax() { return max[1]; }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        List<Integer> vals = new ArrayList<>();
        while (fs.hasNext()) vals.add(fs.nextInt());
        if (vals.isEmpty()) return;

        int n = vals.get(0);
        if (vals.size() < 1 + 2 * n) return;

        int[] a = new int[n];
        int[] b = new int[n];
        int[] coords = new int[2 * n];
        for (int i = 0; i < n; i++) {
            a[i] = vals.get(1 + 2 * i);
            b[i] = vals.get(1 + 2 * i + 1);
            if (a[i] > b[i]) {
                int t = a[i]; a[i] = b[i]; b[i] = t;
            }
            coords[2 * i] = a[i];
            coords[2 * i + 1] = b[i];
        }

        Arrays.sort(coords);
        int m = 0;
        int[] uniq = new int[coords.length];
        for (int x : coords) {
            if (m == 0 || uniq[m - 1] != x) uniq[m++] = x;
        }

        // Sections correspond to intervals between uniq[i] and uniq[i+1], count = m-1
        int sections = Math.max(0, m - 1);
        if (sections == 0) {
            System.out.println("0 0");
            return;
        }

        SegTree seg1 = new SegTree(sections);
        int policy1 = 0;

        int[] diff = new int[sections + 1];

        for (int i = 0; i < n; i++) {
            int l = lowerBound(uniq, m, a[i]);
            int r = lowerBound(uniq, m, b[i]);
            if (l < r) {
                seg1.add(l, r, 1);
                policy1 = Math.max(policy1, seg1.queryMax());

                diff[l]++;
                diff[r]--;
            }
        }

        int cur = 0, policy2 = 0;
        for (int i = 0; i < sections; i++) {
            cur += diff[i];
            policy2 = Math.max(policy2, cur);
        }

        System.out.println(policy1 + " " + policy2);
    }

    static int lowerBound(int[] a, int n, int x) {
        int l = 0, r = n;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] < x) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        boolean hasNext() throws IOException {
            int c;
            while ((c = read()) != -1) {
                if (!Character.isWhitespace(c)) {
                    ptr--;
                    return true;
                }
            }
            return false;
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
